import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    if n == 0:
        print(0)
        return

    level_order = []
    for _ in range(n):
        val_str = next(iterator)
        if val_str == 'null':
            level_order.append(None)
        else:
            level_order.append(int(val_str))

    MOD = 10**9 + 7

    if n == 1:
        val = level_order[0]
        print((val * val) % MOD)
        return

    total_sum = 0

    left_idx = 0
    right_idx = n - 1

    while left_idx < right_idx:
        left_val = level_order[left_idx]
        right_val = level_order[right_idx]

        if left_val is not None and right_val is not None:
            prod = (left_val * right_val) % MOD
            total_sum = (total_sum + prod) % MOD

        left_idx += 1
        right_idx -= 1

    mid_idx = n // 2
    if n % 2 == 1:
        mid_val = level_order[mid_idx]
        if mid_val is not None:
            prod = (mid_val * mid_val) % MOD
            total_sum = (total_sum + prod)

    print(total_sum % MOD)

if __name__ == "__main__":
    main()
